INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3425187, 476441, 66635, '<td valign="top">Extremely sexy.  But she looks wickedly tough as if she needs no protecting.</td>', 'Extremely sexy.  But she looks wickedly tough as if she needs no protecting.', '2007-03-03 09:42:08.000000', NULL, 1),
(3425190, 474799, 66635, '<td valign="top">Cool shot.  My eye was immediately drawn, however, to the fact that you are slightly off center -- slightly to the left (not the model, the photographer).  I mean, on the second brick wall, you have 1.5 brick lengths on the right and less than 1 on the left.  This is carried on to the third wall.  Maybe this was your intent.  Maybe I am too left brained and demanding of order and symmetry.  But it jumps out at me.</td>', 'Cool shot.  My eye was immediately drawn, however, to the fact that you are slightly off center -- slightly to the left (not the model, the photographer).  I mean, on the second brick wall, you have 1.5 brick lengths on the right and less than 1 on the left.  This is carried on to the third wall.  Maybe this was your intent.  Maybe I am too left brained and demanding of order and symmetry.  But it jumps out at me.', '2007-03-03 09:46:52.000000', NULL, 1),
